// Generates crates/aether-server/src/placement/data.rs from the vanilla data
// pack's block tags.
//
//   tools/gen/placement.js [pack-root]
//
// `pack-root` (default $AETHER_VANILLA_PACK, then ./versions/1.21.11, then
// /opt/aether/vanilla/1.21.11) may be the unpacked server jar, the pack root,
// `data/minecraft`, or `data/minecraft/worldgen`; the script finds the block
// tags under it. Run it the same way `gamedata.js` is run, once per release.
//
// The output is checked in ("Do not edit by hand"); the server uses it as the
// no-pack fallback and `placement/rules.rs` consults the same names. A tag is
// resolved recursively (a value of `#minecraft:dirt` expands to dirt's own
// blocks), exactly as the game's tag loader does.
const fs = require('fs')
const path = require('path')

const root =
  process.argv[2] ||
  process.env.AETHER_VANILLA_PACK ||
  ['versions/1.21.11', '/opt/aether/vanilla/1.21.11'].find(p => p && fs.existsSync(p)) ||
  ''

// Locate `data/minecraft` from whatever the caller pointed us at: the pack
// root, `data/minecraft`, `data/minecraft/worldgen`, or the unpacked jar
// (`data/data/minecraft`, as `tools/gen/regen.sh` lays it out).
function findDataMinecraft(dir) {
  const candidates = [
    dir,
    path.join(dir, 'data/minecraft'),
    path.join(dir, 'data/data/minecraft'),
    path.join(dir, 'data'),
    path.join(dir, 'worldgen'),
  ]
  for (const c of candidates) {
    if (fs.existsSync(path.join(c, 'tags/block'))) return c
  }
  return null
}

const dataMc = findDataMinecraft(root)
if (!dataMc) {
  console.error(`placement: no block tags under ${root || '(unset $AETHER_VANILLA_PACK)'}`)
  process.exit(2)
}
const tagsDir = path.join(dataMc, 'tags/block')

const cache = new Map()
function tagPath(id) {
  const bare = id.replace(/^#/, '').replace(/^minecraft:/, '')
  return path.join(tagsDir, `${bare}.json`)
}

// Resolve a block tag to its concrete block names, in file order, first
// occurrence kept — the order `getRandomElementOf` indexes into and the order
// the reverse index reads best in.
function resolve(id) {
  const key = id.replace(/^#/, '').replace(/^minecraft:/, '')
  if (cache.has(key)) return cache.get(key)
  cache.set(key, []) // cycle guard: a tag is empty while being resolved
  const file = tagPath(key)
  if (!fs.existsSync(file)) {
    cache.set(key, [])
    return []
  }
  const json = JSON.parse(fs.readFileSync(file, 'utf8'))
  const out = []
  for (const v of json.values || []) {
    const name = typeof v === 'string' ? v : v && v.id
    if (!name) continue
    const members = name.startsWith('#') ? resolve(name) : [name.includes(':') ? name : `minecraft:${name}`]
    for (const m of members) if (!out.includes(m)) out.push(m)
  }
  cache.set(key, out)
  return out
}

const q = s => JSON.stringify(s)
const out = []
const w = s => out.push(s)

w('//! Block placement data, generated by `tools/gen/placement.js` from the')
w("//! vanilla 1.21.11 data pack's block tags. Do not edit by hand.")
w('//!')
w('//! The replaceable list is the authoritative `#minecraft:replaceable` tag;')
w('//! each other array is one tag expanded to concrete block names, in pack')
w('//! order. `placement::rules` reads these when no data pack is configured.')
w('#![allow(clippy::all)]')
w('')

function emit(name, tag) {
  const members = resolve(tag)
  w(`/// \`#${tag}\` (${members.length} blocks).`)
  // `rustfmt::skip` keeps the generated member-per-line layout: without it
  // `cargo fmt` reflows short arrays and the file drifts from the generator.
  w('#[rustfmt::skip]')
  w(`pub static ${name}: [&str; ${members.length}] = [`)
  for (const m of members) w(`    ${q(m)},`)
  w('];')
  w('')
}

emit('REPLACEABLE', 'minecraft:replaceable')
emit('DIRT', 'minecraft:dirt')
emit('SAND', 'minecraft:sand')
emit('LEAVES', 'minecraft:leaves')
emit('DRY_VEGETATION_MAY_PLACE_ON', 'minecraft:dry_vegetation_may_place_on')
emit('BAMBOO_PLANTABLE_ON', 'minecraft:bamboo_plantable_on')
emit('BIG_DRIPLEAF_PLACEABLE', 'minecraft:big_dripleaf_placeable')
emit('SMALL_DRIPLEAF_PLACEABLE', 'minecraft:small_dripleaf_placeable')
emit('AZALEA_GROWS_ON', 'minecraft:azalea_grows_on')
emit('SNOW_LAYER_CAN_SURVIVE_ON', 'minecraft:snow_layer_can_survive_on')
emit('SNOW_LAYER_CANNOT_SURVIVE_ON', 'minecraft:snow_layer_cannot_survive_on')
emit('MUSHROOM_GROW_BLOCK', 'minecraft:mushroom_grow_block')
emit('JUNGLE_LOGS', 'minecraft:jungle_logs')
emit('ICE', 'minecraft:ice')

while (out.length && out[out.length - 1] === '') out.pop()
process.stdout.write(out.join('\n') + '\n')
